import{z as i,x as p,o as e,c as A,q as B,j as r,D as t,d as E,s,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Roll 有效价差估计","description":"","frontmatter":{"title":"Roll 有效价差估计","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/roll-effective-spread.md","filePath":"quant/roll-effective-spread.md","lastUpdated":1791063341000}'),c={name:"quant/roll-effective-spread.md"};function d(h,a,C,m,u,D){const o=p("Mermaid");return e(),A("div",null,[a[2]||(a[2]=B('<h1 id="roll-有效价差估计" tabindex="-1">Roll 有效价差估计 <a class="header-anchor" href="#roll-有效价差估计" aria-label="Permalink to &quot;Roll 有效价差估计&quot;">​</a></h1><div class="epigraph"><p>有效价差不必写在报价上：若成交只是在价值两侧弹跳，相邻价格变化的负协方差就已经给出宽度；估计的任务是把这条协方差从样本里稳定地读出来，并承认它何时读不出来。</p><footer>—— 据 Roll, Journal of Finance, 1984，及其后作为交易成本代理的估计实践</footer></div><p><a href="/quant/pastor-stambaugh">上一课</a>把流动性收在日度 γ：做市资本的共同性，水平与创新分开。频率再往下，弹跳自己会报出价差。<a href="/quant/roll-model">Roll 模型</a> 把成交价写成鞅价值加买卖弹跳，并导出 \\(s=2\\sqrt{-\\mathrm{Cov}(\\Delta P_t,\\Delta P_{t-1})}\\)。那一篇写识别假设：价值鞅、方向独立、价差常数。本篇写把它<strong>当作有效价差估计量</strong>时的采样、失败值、以及和报价有效价差的对照。Huang–Stoll 意义上的有效价差是 \\(2D(P-M)\\)，有中点就能直接算；Roll 估计是没有中点、甚至没有报价时的隐含测度。两者量纲相同，数据需求与偏误来源不同。不要把模型推导再抄一遍，这里只关心：样本协方差怎样变成一个可进入截面回归或成本模型的数字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接算法需要同步的成交与 BBO。历史日线、早期场外、部分债券与外汇报价残缺时，只剩价格序列。若用相邻价格的平均绝对变化当价差，价值波动会进去；若用报价价差的日平均，又可能没有报价。Roll 公式把「可预测的负相关」全部归因于弹跳，从而给出一个只用 \\(P_t\\) 的 \\(s\\)。</p><p>估计问题立刻出现。第一，采样频率：日收盘价的 \\(\\Delta P\\) 含隔夜信息，一阶相关不必为负；逐笔成交最接近原意，但方向持续会让协方差变正。第二，正协方差：样本里 \\(\\widehat{\\mathrm{Cov}}\\gt 0\\) 时开方无定义，软件若取绝对值是在伪造弹跳。第三，小样本：一个月的日数据只有约二十个差分，协方差估计极噪，截面排序可以，个股水平不能当高频仪表。问题是给出一套可重复的计算规则，使 \\(s\\) 在「假设大致成立」时接近有效价差，在不成立时报告失败而不是一个假数字。</p><h3 id="有效价差与报价价差不是同一个靶" tabindex="-1">有效价差与报价价差不是同一个靶 <a class="header-anchor" href="#有效价差与报价价差不是同一个靶" aria-label="Permalink to &quot;有效价差与报价价差不是同一个靶&quot;">​</a></h3><p>报价价差是 \\(A-B\\)，可以长期无成交。有效价差度量主动方相对中点实际付了多少。Roll 估的是后者的隐含水平：弹跳幅度对应成交发生在 \\(V\\pm s/2\\)。若大量成交在价差内部，直接有效价差小于报价价差，Roll 也应更接近有效而非报价。若成交经常打穿，Roll 可能大于报价。用 Roll 去检验「哪个市场报价更窄」是问错对象；应用它去近似「没有中点时成交有多贵」。</p><p><span class="marginnote">日收盘价序列上的 Roll 估计，测的是收盘成交（或官方收盘价）的弹跳，不是全日成交的平均有效价差。把 CRSP 日收益的协方差开方，再解释为「这只股票这个月的平均买卖价差」，采样已经换了对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在选定的价格序列 \\(\\{P_t\\}\\) 上计算一阶差分 \\(\\Delta P_t\\)，样本协方差 \\(c=\\widehat{\\mathrm{Cov}}(\\Delta P_t,\\Delta P_{t-1})\\)。若 \\(c\\lt 0\\)，</p> \\[\\hat s = 2\\sqrt{-c}. \\]<p><span class="marginnote">「弹跳」可以类比乒乓球在两条线之间来回：价值是中间线，成交一会儿贴在买价、一会儿贴在卖价，于是买完价小跌、卖完价小涨，相邻两次价格变化符号总相反。这层「负相关」就是价差留在价格序列里的指纹——协方差一开方，指纹就报出宽度。</span></p><p>若价格是对数，先决定要的是对数价差还是价格单位价差；混用会让截面不可比。常用成交事件序列或日历分钟的 last；先聚合成五日再差分，会把多次弹跳平均掉，\\(|c|\\) 变小，\\(\\hat s\\) 偏低。窗长与公布频率匹配：月度因子研究用月内日度或月内逐笔再平均到月；高频监控用滚动成交笔数而不是滚动时钟。</p><p>\\(c\\gt 0\\) 时的处理必须预先承诺：记缺失、记零，或改用贝叶斯收缩（Hasbrouck 把 Roll 状态空间化，用 Gibbs 把价差限制在正数并吸收方向持续）。禁止对 \\(c\\) 取绝对值再开方。报告时同时给出失败比例：若某市场某月一半股票 \\(c\\gt 0\\)，该月的截面「Roll 价差」已被选择偏差污染——留下来的多半是弹跳仍占主导的冷门股。</p><p><span class="marginnote">初学者容易看到「Roll 价差下降」就断定流动性改善：在知情流涌入的月份，协方差被信息推正，失败率飙升、留下的估计还系统性偏低——读数下降可能恰恰说明真实价差变宽了。先看失败比例，再读数字本身。</span></p><h3 id="与直接有效价差对齐的实验" tabindex="-1">与直接有效价差对齐的实验 <a class="header-anchor" href="#与直接有效价差对齐的实验" aria-label="Permalink to &quot;与直接有效价差对齐的实验&quot;">​</a></h3><p>有 BBO 的子样本上，把同窗的平均 \\(\\mathrm{ES}=2D(P-M)\\) 对 \\(\\hat s\\) 做截面回归。斜率接近 1、截距接近 0，说明弹跳识别在该采样上成立。\\(\\hat s\\) 系统性更大，可能是方向持续被忽略、或中点定义与成交时间戳不一致；系统性更小，可能是聚合过度或价格改善使弹跳小于报价宽度。这组对照是估计量的设定检验，不是「再用 Roll 发现一次有效价差」。</p><p>方向分类误差会压低直接 ES，却不一定以同样方式压低 Roll——Roll 不用 \\(D\\)。因此在分类质量差的数据里，Roll 有时看起来「更稳」，那是因为它回答了更粗的问题，不是因为它更准确。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>当假设近似成立，相邻成交倾向于买卖交替，价格在价值两侧弹，\\(\\Delta P\\) 负相关，\\(|c|\\) 约为 \\((s/2)^2\\)。估计量读到的就是这笔二阶矩。当知情交易让买之后价值上移，相邻 \\(\\Delta P\\) 的乘积被推向正，\\(|c|\\) 缩小甚至变号，\\(\\hat s\\) 偏低或失败——此时真实有效价差往往更高（逆向选择），Roll 往反方向走。这是作为成本代理最危险的性质：信息越毒，隐含弹跳测度越像在说「价差变窄了」。</p>',21)),(e(),r(n,null,{default:t(()=>[s(o,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOUNCE%5B%22%E4%B9%B0%E5%8D%96%E4%BA%A4%E6%9B%BF%EF%BC%9A%E4%BB%B7%E6%A0%BC%E5%9C%A8%E4%BB%B7%E5%80%BC%E4%B8%A4%E4%BE%A7%E5%BC%B9%22%5D%20--%3E%20NEG%5B%22%E7%9B%B8%E9%82%BB%20%CE%94P%20%E4%B9%98%E7%A7%AF%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20TOX%5B%22%E7%9F%A5%E6%83%85%E6%B5%81%EF%BC%9A%E4%B9%B0%E5%90%8E%E4%BB%B7%E5%80%BC%E4%B8%8A%E7%A7%BB%22%5D%20--%3E%20POS%5B%22%E7%9B%B8%E9%82%BB%20%CE%94P%20%E4%B9%98%E7%A7%AF%E8%A2%AB%E6%8E%A8%E5%90%91%E6%AD%A3%22%5D%0A%20%20NEG%20--%3E%20C1%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%20c%20%E4%B8%BA%E8%B4%9F%EF%BC%9A%7Cc%7C%20%E2%89%88%20(s%2F2)%C2%B2%22%5D%0A%20%20POS%20--%3E%20C2%5B%22c%20%E4%B8%8A%E7%A7%BB%EF%BC%9A%7Cc%7C%20%E7%BC%A9%E5%B0%8F%E7%94%9A%E8%87%B3%E5%8F%98%E5%8F%B7%22%5D%0A%20%20C1%20--%3E%20S%5B%22%C5%9D%20%E8%AF%BB%E5%87%BA%E6%AD%A3%E5%B8%B8%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20C2%20--%3E%20F%5B%22%C5%9D%20%E5%81%8F%E4%BD%8E%E6%88%96%E5%A4%B1%E8%B4%A5%EF%BC%9A%E7%9C%9F%E5%AE%9E%E4%BB%B7%E5%B7%AE%E5%8F%8D%E8%80%8C%E6%9B%B4%E5%AE%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<p><span class="marginnote">给弹跳代个数：若价差 \\(s=0.20\\) 元，成交价在价值两侧各偏 \\(s/2=0.10\\) 元，理论协方差 \\(|c|\\approx 0.1^2=0.01\\)，代入 \\(\\hat s=2\\sqrt{0.01}=0.20\\)——正好还原价差。模型读的只是这笔二阶矩，价值本身的涨跌它一概不认。</span></p><p>存货诱导的中点漂移同样污染 \\(c\\)，但方向不一定与信息相同。短暂的同向报价调整会减少负相关；把 \\(\\hat s\\) 解释为<a href="/quant/spread-decomposition">价差分解</a>里的处理成本，会把存货与信息的永久成分漏掉。工程上，Roll 更适合当「无报价市场的宽度代理」或「有报价时的弹跳诊断」，不适合当逆向选择的主度量。</p><h3 id="频率选择改变的是对象不是精度" tabindex="-1">频率选择改变的是对象不是精度 <a class="header-anchor" href="#频率选择改变的是对象不是精度" aria-label="Permalink to &quot;频率选择改变的是对象不是精度&quot;">​</a></h3><p>把逐笔差分换成分钟 last 的差分，格子内的多次弹跳被净掉，留下的相关更像分钟收益的微观结构噪声。把日收盘连成序列，隔夜信息占主导，弹跳只是收盘那一笔的买卖。没有一种频率是「更精确的同一个 \\(s\\)」；每种频率对应一种弹跳。写进研究的应是「事件时间成交的 Roll \\(s\\)」或「日收盘的 Roll \\(s\\)」，并与同频率的直接 ES 对照。</p><p><span class="marginnote">Harris 讨论交易成本测量时，隐含测度的价值正在于没有报价的市场。有 L1 之后，优先用有效价差；Roll 留下来的工作是设定检验与长历史拼接，而不是替代中点算法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>价格离散到一个 tick、大量 \\(\\Delta P=0\\)，协方差被压低，\\(\\hat s\\) 偏小。拆股与分红必须先调整，否则差分里的跳被当成弹跳。多交易所并行时，把所有成交简单按时间排成一条序列，会把同一价值发现的腿间弹跳算进去，也可能把延迟造成的假回跳算进去。应先按主市场或按中点对齐规则过滤。</p><p>不要把月度 Roll \\(s\\) 当作 <a href="/quant/pastor-stambaugh">Pástor–Stambaugh</a> 的 γ：一个是价差宽度，一个是成交额的临时冲击。也不要用 Roll \\(s\\) 去扣动量空头的收益并声称「成本后动量消失」——空头腿往往正是 \\(c\\gt 0\\)、估计失败最严重的那些股票。与 <a href="/quant/corwin-schultz">Corwin–Schultz</a> 并列时，应报告两者的相关、失败率，以及隔夜处理是否一致，而不是平均成一个「综合价差」。</p><p><span class="marginnote">理论出处仍是 Roll, <em>A Simple Implicit Measure of the Effective Bid-Ask Spread in an Efficient Market</em>, Journal of Finance, 1984。作为估计实践，应同时交代采样、正协方差规则与对照样本。Hasbrouck 的贝叶斯 Roll 是正约束下的另一估计量，不是把负号拿掉。</span></p>',9)),(e(),r(n,null,{default:t(()=>[s(o,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%B7%E6%A0%BC%E5%BA%8F%E5%88%97%20P%22%5D%20--%3E%20D%5B%22%E5%B7%AE%E5%88%86%20%CE%94P%22%5D%0A%20%20D%20--%3E%20C%5B%22%E4%B8%80%E9%98%B6%E5%8D%8F%E6%96%B9%E5%B7%AE%20c%22%5D%0A%20%20C%20--%3E%7C%22c%20%EF%BC%9C%200%22%7C%20S%5B%22s%20%3D%202%20sqrt(-c)%22%5D%0A%20%20C%20--%3E%7C%22c%20%3E%200%22%7C%20F%5B%22%E7%BC%BA%E5%A4%B1%E6%88%96%E9%9B%B6%EF%BC%8C%E7%A6%81%E6%AD%A2%E5%8F%96%E7%BB%9D%E5%AF%B9%E5%80%BC%22%5D%0A%20%20S%20--%3E%20CHK%5B%22%E4%B8%8E%E5%90%8C%E7%AA%97%E7%9B%B4%E6%8E%A5%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%E5%AF%B9%E7%85%A7%22%5D%0A%20%20INF%5B%22%E6%96%B9%E5%90%91%E6%8C%81%E7%BB%AD%20%2F%20%E4%BF%A1%E6%81%AF%22%5D%20-.-%3E%7C%22c%20%E4%B8%8A%E7%A7%BB%22%7C%20C%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l("h2",{id:"小结",tabindex:"-1"},[E("小结 "),l("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=l("ul",null,[l("li",null,"Roll 有效价差估计把负的一阶协方差开方，是无中点时的隐含宽度，不是报价价差。"),l("li",null,"采样频率决定对象：逐笔、分钟、日收盘不是同一个 \\(s\\) 的精度阶梯。"),l("li",null,"协方差为正时应报告失败；取绝对值会伪造弹跳，且在毒性高时偏误最危险。"),l("li",null,"有 BBO 时用直接有效价差，把 Roll 当对照；成本扣减不要用失败率高的月度截面。"),l("li",null,"出处：Roll, Journal of Finance, 1984；估计纪律见后续交易成本测量文献。")],-1))])}const F=i(c,[["render",d]]);export{P as __pageData,F as default};
